import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

os.environ["CXX"] = "hipcc"

# Custom GELU kernel
gelu_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void gelu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float xi = x[idx];
        float cube = xi * xi * xi;
        float inner = 0.044715f * cube + xi;
        float mult = sqrtf(2.0f / M_PI) * inner;
        float tanh_val = tanhf(mult);
        out[idx] = 0.5f * xi * (1.0f + tanh_val);
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

gelu_op = load_inline(
    name="gelu_op",
    cpp_sources=gelu_cpp_source,
    functions=["gelu_hip"],
    verbose=True,
)

# Fused FlashAttention-style kernel
fused_attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

#define BLOCK_SIZE 64

template<int BLOCK_SIZE_M, int BLOCK_SIZE_N, int BLOCK_SIZE_K>
__global__ void fused_attention_kernel(
    const float* queries,
    const float* keys,
    const float* values,
    const float* qkv_weight,
    const float* proj_weight,
    const float* qkv_bias,
    const float* proj_bias,
    float* output,
    int B, int T, int C, int n_head, int hs, int maxT
) {
    int b = blockIdx.x;
    int head_idx = blockIdx.y;
    int row_start = blockIdx.z * BLOCK_SIZE_M;

    extern __shared__ float shared_mem[];
    float* shared_q = shared_mem;
    float* shared_k = shared_q + BLOCK_SIZE_M * hs;
    float* shared_v = shared_k + BLOCK_SIZE_N * hs;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int local_i = threadIdx.y;
    int local_j = threadIdx.x;

    int global_i = row_start + local_i;

    __shared__ float max_val[BLOCK_SIZE_M];
    __shared__ float sum_exp[BLOCK_SIZE_M];

    if (local_j == 0 && global_i < T) {
        max_val[local_i] = -INFINITY;
        sum_exp[local_i] = 0.0f;
    }
    __syncthreads();

    float local_max = -INFINITY;
    float local_sum = 0.0f;

    if (global_i < T) {
        int qkv_offset = b * (C * 3) + head_idx * hs;
        int proj_offset = b * C + head_idx * hs;

        for (int t = 0; t < T; ++t) {
            float qk_val = 0.0f;
            float attn_score = 0.0f;

            for (int d = 0; d < hs; ++d) {
                int q_idx = b * T * C + global_i * C + head_idx * hs + d;
                int k_idx = b * T * C + t * C + head_idx * hs + d;

                float q_val = 0.0f;
                float k_val = 0.0f;

                for (int c = 0; c < C; ++c) {
                    q_val += queries[q_idx] * qkv_weight[(head_idx * hs + d) * C + c] + (d < hs ? qkv_bias[head_idx * hs + d] : 0);
                    k_val += keys[k_idx + (c - (c % C)) / T] * qkv_weight[(C + head_idx * hs + d) * C + c];
                }

                qk_val += q_val * k_val;
            }

            qk_val *= 1.0f / sqrtf((float)hs);

            if (t > global_i) {
                attn_score = -INFINITY;
            } else {
                attn_score = qk_val;
            }

            if (attn_score > local_max) {
                local_max = attn_score;
            }
            shared_q[local_i * T + t] = attn_score;
        }

        __syncthreads();

        float sum_exp_local = 0.0f;
        for (int t = 0; t <= global_i; ++t) {
            shared_q[local_i * T + t] = expf(shared_q[local_i * T + t] - local_max);
            sum_exp_local += shared_q[local_i * T + t];
        }

        sum_exp[local_i] = sum_exp_local;
        __syncthreads();

        for (int head_d = 0; head_d < hs; ++head_d) {
            float acc = 0.0f;
            for (int t = 0; t <= global_i; ++t) {
                int v_idx = b * T * C + t * C + head_idx * hs + head_d;
                float v_val = 0.0f;

                for (int c = 0; c < C; ++c) {
                    v_val += values[v_idx + (c - (c % C)) / T] * qkv_weight[(2 * C + head_idx * hs + head_d) * C + c];
                }

                acc += shared_q[local_i * T + t] * v_val;
            }
            acc /= sum_exp_local;

            int out_idx = b * T * C + global_i * C + head_idx * hs + head_d;
            float proj_val = 0.0f;
            for (int c = 0; c < C; ++c) {
                proj_val += acc * proj_weight[head_idx * hs + head_d, c];
            }
            proj_val += proj_bias[head_idx * hs + head_d];
            output[out_idx] = proj_val;
        }
    }
}

torch::Tensor fused_attention_hip(
    torch::Tensor x,
    torch::Tensor qkv_weight,
    torch::Tensor qkv_bias,
    torch::Tensor proj_weight,
    torch::Tensor proj_bias,
    int n_head
) {
    auto B = x.size(0);
    auto T = x.size(1);
    auto C = x.size(2);
    int hs = C / n_head;
    int maxT = T;

    const int BLOCK_SIZE = 64;
    dim3 grid(B, n_head, (T + BLOCK_SIZE - 1) / BLOCK_SIZE);
    dim3 block(BLOCK_SIZE, 4);

    auto output = torch::zeros_like(x);

    fused_attention_kernel<64, 128, 16><<<grid, block, BLOCK_SIZE * 3 * hs * sizeof(float)>>>(
        x.data_ptr<float>(),
        x.data_ptr<float>(),
        x.data_ptr<float>(),
        qkv_weight.data_ptr<float>(),
        proj_weight.data_ptr<float>(),
        qkv_bias.data_ptr<float>(),
        proj_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, T, C, n_head, hs, maxT
    );

    return output;
}
"""

fused_attention = load_inline(
    name="fused_attention",
    cpp_sources=fused_attention_cpp_source,
    functions=["fused_attention_hip"],
    verbose=True,
)

class OptimizedGELU(nn.Module):
    def __init__(self):
        super(OptimizedGELU, self).__init__()
        self.gelu = gelu_op

    def forward(self, x):
        return self.gelu.gelu_hip(x)

class OptimizedCausalSelfAttention(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.n_head = n_head
        self.n_embd = n_embd
        self.hs = n_embd // n_head

        # key, query, value projections
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)

        self.fused_attention = fused_attention

    def forward(self, x):
        return self.fused_attention.fused_attention_hip(
            x,
            self.c_attn.weight,
            self.c_attn.bias,
            self.c_proj.weight,
            self.c_proj.bias,
            self.n_head
        )

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = OptimizedCausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = OptimizedGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x)))) # MLP forward

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x

batch_size = 128
max_seqlen = 1024
seq_len = 512
n_embd = 768
n_head = 8
attn_pdrop = 0.0
resid_pdrop = 0.0

def get_inputs():
    return [torch.rand(batch_size, seq_len, n_embd, device='cuda', dtype=torch.float32)]

def get_init_inputs():
    return [n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen]

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

os.environ["CXX"] = "hipcc"

# Custom GELU kernel
gelu_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void gelu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float xi = x[idx];
        float cube = xi * xi * xi;
        float inner = 0.044715f * cube + xi;
        float mult = sqrtf(2.0f / M_PI) * inner;
        float tanh_val = tanhf(mult);
        out[idx] = 0.5f * xi * (1.0f + tanh_val);
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

gelu_op = load_inline(
    name="gelu_op",
    cpp_sources=gelu_cpp_source,
    functions=["gelu_hip"],
    verbose=True,
)

# Custom element-wise attention kernel
attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void attention_kernel(
    const float* q,
    const float* k,
    const float* v,
    float* out,
    int B, int n_head, int T, int C, int hs, int maxT
) {
    int b = blockIdx.x;
    int head = blockIdx.y;
    int t_out = blockIdx.z * blockDim.y + threadIdx.y;
    int d = threadIdx.x;

    if (t_out >= T || d >= hs) return;

    int idx = b * n_head * T * hs + head * T * hs + t_out * hs + d;

    float max_val = -INFINITY;
    for (int t = 0; t <= t_out && t < T; ++t) {
        float qk = 0.0f;
        for (int dh = 0; dh < hs; ++dh) {
            int q_idx = b * n_head * T * hs + head * T * hs + t_out * hs + dh;
            int k_idx = b * n_head * T * hs + head * T * hs + t * hs + dh;
            qk += q[q_idx] * k[k_idx];
        }
        qk *= 1.0f / sqrtf((float)hs);

        if (qk > max_val) {
            max_val = qk;
        }
    }

    float sum_exp = 0.0f;
    float sum_val = 0.0f;
    for (int t = 0; t <= t_out && t < T; ++t) {
        float qk = 0.0f;
        for (int dh = 0; dh < hs; ++dh) {
            int q_idx = b * n_head * T * hs + head * T * hs + t_out * hs + dh;
            int k_idx = b * n_head * T * hs + head * T * hs + t * hs + dh;
            qk += q[q_idx] * k[k_idx];
        }
        qk *= 1.0f / sqrtf((float)hs);

        float exp_val = expf(qk - max_val);
        sum_exp += exp_val;

        float v_val = 0.0f;
        for (int dh = 0; dh < hs; ++dh) {
            int v_idx = b * n_head * T * hs + head * T * hs + t * hs + dh;
            v_val += v[v_idx];
        }
        sum_val += exp_val * v_val;
    }

    float attn_out = sum_val / sum_exp;

    out[idx] = attn_out;
}

torch::Tensor attention_hip(torch::Tensor x, int n_head) {
    auto B = x.size(0);
    auto T = x.size(1);
    auto C = x.size(2);
    int hs = C / n_head;
    int maxT = T;

    auto q = x.clone();
    auto k = x.clone();
    auto v = x.clone();
    auto out = torch::zeros_like(x);

    dim3 grid(B, n_head, (T + 15) / 16);
    dim3 block(hs, 16);

    attention_kernel<<<grid, block>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        B, n_head, T, C, hs, maxT
    );

    return out;
}
"""

attention_op = load_inline(
    name="attention_op",
    cpp_sources=attention_cpp_source,
    functions=["attention_hip"],
    verbose=True,
)

class OptimizedGELU(nn.Module):
    def __init__(self):
        super(OptimizedGELU, self).__init__()
        self.gelu = gelu_op

    def forward(self, x):
        return self.gelu.gelu_hip(x)

class OptimizedCausalSelfAttention(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.n_head = n_head
        self.n_embd = n_embd

        # key, query, value projections
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)

        self.attn_op = attention_op

    def forward(self, x):
        B, T, C = x.size()

        # Linear projection for Q, K, V - keeping this in PyTorch for now
        qkv = self.c_attn(x)
        q, k, v = qkv.split(self.n_embd, dim=2)

        # Reshape for multi-head attention
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        # Custom attention kernel
        y = self.attn_op.attention_hip(x, self.n_head)
        y = y.view(B, T, C)

        # Output projection
        y = self.c_proj(y)
        return y

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = OptimizedCausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = OptimizedGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x)))) # MLP forward

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x

