#define BLOCK_SIZE 256

// Kernel to fuse residual add and LayerNorm for each token
__global__ void fused_residual_layernorm_kernel(
    const float* attn_output,  // Input from attention: (seq_len, batch_size, embed_dim)
    const float* residual,     // Residual connection: (seq_len, batch_size, embed_dim)
    const float* weight,       // LayerNorm weight: (embed_dim,)
    const float* bias,         // LayerNorm bias: (embed_dim,)
    float* output,             // Output: (seq_len, batch_size, embed_dim)
    int seq_len, int batch_size, int embed_dim) {

    // Each warp processes one token for better performance
    int token_idx = blockIdx.x;
    int total_tokens = seq_len * batch_size;

    if (token_idx < total_tokens) {
        // Calculate offset for this token
        int offset = token_idx * embed_dim;

        const float* attn_ptr = attn_output + offset;
        const float* residual_ptr = residual + offset;
        float* out_ptr = output + offset;

        // Compute sum for mean calculation (reduction per token)
        float sum = 0.0f;
        for (int i = threadIdx.x; i < embed_dim; i += blockDim.x) {
            float val = attn_ptr[i] + residual_ptr[i];
            sum += val;
            // Store temporarily in output (we'll overwrite it)
            out_ptr[i] = val;
        }

        // Cooperative reduction to compute mean
        __shared__ float shared_mean[BLOCK_SIZE];
        int lane = threadIdx.x % warpSize;
        int warp_id = threadIdx.x / warpSize;

        // Warp-level reduction
        for (int offset_warp = warpSize / 2; offset_warp > 0; offset_warp >>= 1) {
            sum += __shfl_down(sum, offset_warp);
        }

        // Store warp result
        if (lane == 0) {
            shared_mean[warp_id] = sum;
        }
        __syncthreads();

        // Final reduction
        if (threadIdx.x == 0) {
            float total_sum = 0.0f;
            int num_warps = blockDim.x / warpSize;
            for (int i = 0; i < num_warps; i++) {
                total_sum += shared_mean[i];
            }
            shared_mean[0] = total_sum / embed_dim;  // This is the mean
        }
        __syncthreads();

        float mean = shared_mean[0];

        // Compute variance
        float var_sum = 0.0f;
        for (int i = threadIdx.x; i < embed_dim; i += blockDim.x) {
            float diff = out_ptr[i] - mean;
            var_sum += diff * diff;
        }

        // Warp-level reduction for variance
        for (int offset_warp = warpSize / 2; offset_warp > 0; offset_warp >>= 1) {
            var_sum += __shfl_down(var_sum, offset_warp);
        }

        // Store warp result
        if (lane == 0) {
            shared_mean[warp_id] = var_sum;
        }
        __syncthreads();

        // Final reduction for variance
        if (threadIdx.x == 0) {
            float total_var = 0.0f;
            int num_warps = blockDim.x / warpSize;
            for (int i = 0; i < num_warps; i++) {
                total_var += shared_mean[i];
            }
            shared_mean[0] = total_var / embed_dim;  // This is the variance
        }
        __syncthreads();

        float variance = shared_mean[0];
        float inv_std = rsqrtf(variance + 1e-5f);

        // Apply LayerNorm: (x - mean) / sqrt(var + eps) * weight + bias
        for (int i = threadIdx.x; i < embed_dim; i += blockDim.x) {
            float normalized = (out_ptr[i] - mean) * inv_std;
            out_ptr[i] = normalized * weight[i] + bias[i];
        }
    }
}

